import { experiment } from '@caemble/core'
import { Solid } from './geometry'
import { Air, ElasticPlate } from './material'

export default experiment({
  lengthUnit: 'm',
  varsSchema: { length: { min: 0.5, max: 0.5 }, width: { min: 0.1, max: 0.1 }, height: { min: 0.1, max: 0.1 } },
  geometry: ({ vars }) => (
    <>
      <Solid id="air" size={[vars.length, vars.width, vars.height]} position={[vars.length / 2, 0, 0]} materials={{ body: Air() }} />
    </>
  ),
  geometryGroup: { fluid: ['air'] },
  surfaceGroup: {
    inlet: ['air.shape/surface/0'], outlet: ['air.shape/surface/1'],
  },
  recordedData: {
    pressure: { task: 'acoustics', output: 'pressure' },
    pressureProbe: { task: 'acoustics', output: 'pressureProbe' },
  },
})

files.material.tsx:
import { Material } from '@caemble/core'

export const Air = () => new Material('Air', {
  color: '#9bc9e7',
  models: { fluid: { model: 'acoustics.homogeneous-fluid@1', parameters: {
    density: { dtype: 'float64', value: 1.2, unit: 'kg.m-3' },
    soundSpeed: { dtype: 'float64', value: 343, unit: 'm.s-1' },
  } } },
})

export const ElasticPlate = () => new Material('Elastic plate', {
  color: '#b4bec8',
  models: { solid: { model: 'mechanics.isotropic-elastic@1', parameters: {
    E: { dtype: 'float64', value: 2e9, unit: 'Pa' },
    nu: { dtype: 'float64', value: 0.3, unit: '1' },
    density: { dtype: 'float64', value: 1200, unit: 'kg.m-3' },
  } } },
})

