import { Box, defineTask } from '@caemble/core'

// Peak exp(+i*omega*t) pressure. Inlet outward normal is -X; the matched outlet is rho*c.
export default defineTask({
  kernel: { name: 'pressure-acoustics', version: '1.1.0' },
  lengthUnit: 'm',
  config: () => ({
    parameters: { spatialResolution: { dtype: 'float64', value: 0.02, quantityKind: 'Length', unit: 'm' } },
    initializations: [
      { methodId: 'acoustics.fluid', target: ['experiment.geometry.fluid'], parameters: {} },
      { methodId: 'acoustics.spectrum', target: [], parameters: {
        frequencies: { dtype: 'float64', quantityKind: 'Frequency', unit: 'Hz',
                       value: [100, 137.5, 175, 212.5, 250, 287.5, 325, 362.5, 400], axes: [{ length: 9 }] },
      } },
    ],
    boundaryConditions: [
      {
        methodId: 'acoustics.normal-velocity', target: ['experiment.surface.inlet'],
        parameters: { amplitude: { dtype: 'float64', value: 1, quantityKind: 'kinematics.Speed', unit: 'm.s-1' },
                      phase: { dtype: 'float64', value: Math.PI, quantityKind: 'Angle', unit: 'rad' } },
      },
      { methodId: 'acoustics.impedance', target: ['experiment.surface.outlet'], parameters: {
        resistance: { dtype: 'float64', value: 1.2 * 343, quantityKind: 'acoustics.SpecificAcousticImpedance', unit: 'Pa.s.m-1' },
      } },
    ],
    outputs: [
      { methodId: 'acoustics.pressure', key: 'pressure', target: ['task.geometry.outputGrid'], parameters: { gridShape: [24, 4, 4] } },
      { methodId: 'acoustics.pressure', key: 'pressureProbe', target: ['task.geometry.probe'], parameters: { gridShape: [1, 1, 1] } },
    ],
    exports: [],
  }),
  geometry: ({ vars }) => <>
    <Box id="output-grid" size={[Number(vars.length), Number(vars.width), Number(vars.height)]} position={[Number(vars.length) / 2, 0, 0]} />
    <Box id="probe" size={[0.001, 0.001, 0.001]} position={[0.8 * Number(vars.length), 0, 0]} />
  </>,
  geometryGroup: { outputGrid: ['output-grid'], probe: ['probe'] },
})
